using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;
public static class RestoreDoorMaterialSerialization{
 public static object Run(){var f=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/C01_Doors/material_serialization.json"));var names=JArray.Parse(File.ReadAllText(f));foreach(var item in names){var m=AssetDatabase.LoadAssetAtPath<Material>((string)item["asset"]);if((bool)item["verifiedRevert"]){m.doubleSidedGI=false;m.SetTexture("_MainTex",null);}else if(m.name=="PF_Glass"||m.name=="PR_VialGlass"){m.doubleSidedGI=false;m.DisableKeyword("_ALPHAPREMULTIPLY_ON");m.SetShaderPassEnabled("DepthOnly",true);m.SetFloat("_SrcBlend",5);m.SetFloat("_DstBlendAlpha",0);m.SetColor("_Color",Color.white);}else if(m.name=="PF_Liquid")m.SetColor("_Color",Color.white);else throw new Exception("Unexpected material");EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);}return new{restored=names.Count};}
}
